// Adapted from ww16 src/domain/dealRegistration.ts:12-53 @ f649784 (+ the role matrix in
// src/lib/auth/permissions.ts:31-71, reduced to the roles that act on deals). The senior
// review's finding 3 fix is APPLIED here: an assigned approver must be the caller
// (astraupskill/06-SOLUTIONS-AND-REVIEW.md:32).
export class ConflictError extends Error {
  constructor(message) {
    super(message);
    this.statusCode = 409;
  }
}
export class ForbiddenError extends Error {
  constructor(message) {
    super(message);
    this.statusCode = 403;
  }
}

const rolePermissions = {
  PLATFORM_ADMIN: ["deal:submit", "deal:approve_sales", "deal:approve_channel", "deal:close"],
  CHANNEL_MANAGER: ["deal:approve_channel", "deal:close"],
  SALES_REP: ["deal:approve_sales", "deal:close"],
  PARTNER_ADMIN: ["deal:submit"],
  PARTNER_SELLER: ["deal:submit"],
};

function assertPermission(session, permission) {
  if (!rolePermissions[session.role].includes(permission)) {
    throw new ForbiddenError(`Role ${session.role} cannot ${permission}.`);
  }
}

/** Only the assigned approver may act (platform admins excepted); unassigned deals stay open to the role. */
function assertAssigned(session, assignedUserId) {
  if (session.role === "PLATFORM_ADMIN" || !assignedUserId) return;
  if (assignedUserId !== session.userId) {
    throw new ForbiddenError("This deal is assigned to another approver.");
  }
}

const allowedTransitions = {
  DRAFT: ["SUBMITTED"],
  SUBMITTED: ["SALES_APPROVED", "REJECTED"],
  SALES_APPROVED: ["APPROVED", "REJECTED"],
  APPROVED: ["CLOSED_WON", "CLOSED_LOST"],
  REJECTED: [],
  CLOSED_WON: [],
  CLOSED_LOST: [],
};

export function assertDealTransitionAllowed(session, deal, nextStatus) {
  const currentStatus = deal.status;
  if (!allowedTransitions[currentStatus].includes(nextStatus)) {
    throw new ConflictError(`Cannot move a deal from ${currentStatus} to ${nextStatus}.`);
  }

  if (nextStatus === "SUBMITTED") {
    assertPermission(session, "deal:submit");
    return;
  }

  if (nextStatus === "SALES_APPROVED") {
    assertPermission(session, "deal:approve_sales");
    assertAssigned(session, deal.assignedSalesRepId);
    return;
  }

  if (nextStatus === "APPROVED") {
    assertPermission(session, "deal:approve_channel");
    assertAssigned(session, deal.channelManagerId);
    return;
  }

  if (nextStatus === "REJECTED") {
    const salesStage = currentStatus === "SUBMITTED";
    assertPermission(session, salesStage ? "deal:approve_sales" : "deal:approve_channel");
    assertAssigned(session, salesStage ? deal.assignedSalesRepId : deal.channelManagerId);
    return;
  }

  assertPermission(session, "deal:close");
}
